import{_ as r,o as a,c as e,ai as t}from"./chunks/framework.DAbPic9L.js";const c=JSON.parse('{"title":"历世言-道启篇","description":"","frontmatter":{},"headers":[],"relativePath":"mybook/li-shi-yan/dao-qi.md","filePath":"mybook/li-shi-yan/dao-qi.md","lastUpdated":1787215730000}'),o={name:"mybook/li-shi-yan/dao-qi.md"};function b(i,p,s,n,_,d){return a(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="历世言-道启篇" tabindex="-1">历世言-道启篇 <a class="header-anchor" href="#历世言-道启篇" aria-label="Permalink to &quot;历世言-道启篇&quot;">​</a></h1><p>文/晨风不可依米</p><br><p>幼时情谊长，狼多肉却少。</p><p>暗祸难以避，可叹父母心。</p><p>栽赃嫁祸计，童言诉别情。</p><p>委屈难求全，明哲保自身。</p><p>万般皆是命，魂兮何处归？</p><br><p>大变云初起，天意不绝人。</p><p>劫后得以生，相见已無言。</p><p>知面难知心，阴晴不定人。</p><p>扑朔复迷离，一波又三折。</p><p>岁月难静好，何处可安身？</p><br><p>宿命难纠缠，险象连环生。</p><p>目清顾盼飞，纵身赴泥潭。</p><p>奈何惟一赌，破浪勇作舟。</p><p>一遁千里里，破晓露清辉。</p><p>生计颇艰难，福祸两相依。</p><br><p>缘是浮萍聚，宴终不散席。</p><p>相离莫相忘，匆匆又三年。</p><p>别后忆相逢，故人心易变。</p><p>画皮难画骨，破釜勇沉舟。</p><p>柳暗花明处，有舍才有得。</p><br><p>我道路艰行，孤身只形影。</p><p>脱凡明心目，去伪存方真。</p><p>明心方见性，心路渐渐坚。</p><p>人生离别苦，独自黯伤魂。</p><p>烟波微渺间，心中意通明。</p><br><p>初创书诗堂，类己渡由人。</p><p>新宿星雨阁，歌笙把言佳。</p><p>缘是四海汇，皆兮平阳路。</p><p>百般武艺学，千人一力长。</p><p>孤舟摇曳处，纵是桃源乡。</p><br><p>辗转奔故里，不巧闻祸根。</p><p>血海埋深恨，旧事意难平。</p><p>暗中撒罗网，彼道还彼身。</p><p>心中动杀机，回眸魂已惊。</p><p>大道有五十，遁避去其一。</p><br><p>众生皆道往，三千我道一。</p><p>混沌兮有物，恍惚兮無则。</p><p>物竞生五行，無极衍太极。</p><p>天道意制衡，人道自内德。</p><p>先天领后天，盖始启大道。</p><br><p>道常恒無念，無为無不为。</p><p>人约不识源，故以名曰之。</p><p>物象名存之，物反对共生。</p><p>是故物人识，阴阳雌雄辨。</p><p>历往道开言，假物道之外。</p><br><p>源由太初炁，有物而無形。</p><p>無名道之初，有名道之毫。</p><p>言传未是道，無为方是之。</p><p>死生源一炁，皆因聚散离。</p><p>四盘与六合，玄妙道之变。</p><br><p>混沌無形象，有形皆所至。</p><p>形异而混一，受之道乃容。</p><p>混同而合一，名异而实同。</p><p>死生喻终始，道本無始终。</p><p>道衍生生息，世事無常有。</p><br><p>大道废有德，失德继后仁。</p><p>無仁而言义，义往后行礼。</p><p>礼序言言传，道伪身身教。</p><p>而今已实物，难复道归根。</p><p>纵是有至無，难上無無境。</p><br><p>高三就学间，祖母逝闻来。</p><p>人伦纲常在，生物泪別哀。</p><p>道逢缘已结，知之乃道归。</p><p>奈何人伦难，六亲孝慈有。</p><p>纲常背德去，何必悔当初。</p><br><p>道解之無形，死生皆有理。</p><p>不形兮之形，形兮之不形。</p><p>人皆所同知，道废人伦盛。</p><p>道伪人皆往，我道独其行。</p><p>無为皆过客，有缘自相来。</p><br><p>此去兮匆匆，己道身不由。</p><p>往复间然然，命在我不在。</p><p>身兮之非身，道之形蜕也。</p><p>行不知所往，食不知所味。</p><p>世事而無为，相携道与归。</p><br><p>五年悟道一，道所初有成。</p><p>道行皆有物，浩瀚际有理。</p><p>齐物而論道，殊途道乃同。</p><p>此有生于無，無無而道归。</p><p>纵古今有变，然道常恒也。</p><br><p>处道之所为，先天领后天。</p><p>行道之所径，后天引先天。</p><p>道本常循循，道玄衍息息。</p><p>泯然而無迹，经物物不觉。</p><p>天人本一体，炁玄常应物。</p><br><p>道本源一炁，内外皆常有。</p><p>空冥以至虚，宁气而神静。</p><p>心清道归元，抱元一神守。</p><p>五脏应五行，精化气神明。</p><p>坐忘离形体，神游归太虚。</p><br><p>道之非道兮，名之非名兮。</p><p>有物兮無形，無则兮混沌。</p><p>是故有生無，而無以至虚。</p><p>大道简而一，众妙衍而玄。</p><p>天下兮隐隐，道潜常玄在。</p><br><p>然经世义理，欲欲而不终。</p><p>欲多而不禁，欲忘己所欲。</p><p>取一毫利己，拔一毛损众。</p><p>不可得为贵，不可得为贱。</p><p>心若止水兮，道無物可诱。</p><br><p>十年磨一剑，凡尘路启道。</p><p>妄念皆所斩，归凡意平生。</p><p>如是事伊始，师万物于道。</p><p>春冬交昼夜，死生转阴阳。</p><p>万物皆有序，天之道轮回。</p><br><p>道衍而天行，应物于脉理。</p><p>日月星辰转，四时节气更。</p><p>万物衡而作，灵长厚内德。</p><p>虚心实其肉，世無为而进。</p><p>無形而以生，有理终所成。</p><br><p>地载营厚土，万物以本根。</p><p>负浊以濯清，物宁归根静。</p><p>造物于混沌，其象中有精。</p><p>故先天地生，道其成已俱。</p><p>予善善無争，朴道其無锋。</p><br><p>人从事而道，内德而道德。</p><p>明心存真境，明心以见性。</p><p>色音味心狂，道無德其伪。</p><p>德非人道德，其道德非道。</p><p>雌雄难以辨，荣辱由人说。</p>',146)])])}const m=r(o,[["render",b]]);export{c as __pageData,m as default};
